var fs      = require('fs');
var config  = require('config');
var Monitor = require('./lib/monitor');
var apiKey  = require('./lib/apiKey');

// start the monitor, with the API key that the webapp accepts (generated by the webapp when this process runs it)
monitor = Monitor.createMonitor(Object.assign({}, config.monitor, { apiKey: apiKey.forMonitor(config) }));

// load plugins
config.plugins.forEach(function(pluginName) {
  var plugin = require(pluginName);
  if (typeof plugin.initMonitor !== 'function') return;
  console.log('loading plugin %s on monitor', pluginName);
  plugin.initMonitor({
    monitor: monitor,
    config:  config
  });
});

monitor.start();

module.exports = monitor;